fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut distinct_count = 1;
    for i in 1..nums.len() {
        // Since array is sorted, distinct elements will appear as changes
        if nums[i] != nums[i - 1] {
            distinct_count += 1;
        }
    }

    distinct_count
}